      stateReg_bits_target <= 32'h0;
      stateReg_bits_originalTarget <= 32'h0;
      stateReg_bits_linkValid <= 1'h0;
      stateReg_bits_linkAddr <= 5'h0;
      stateReg_bits_linkData <= 32'h0;
      stateReg_bits_pcEx <= 32'h0;
