  assign io_rd_valid = count[5];
  assign io_rd_bits_addr = addr2;
  assign io_rd_bits_data =
    divide2 ? (signed2d ? ~divide + 32'h1 : divide) : signed2r ? ~remain + 32'h1 : remain;
