  output [31:0]  io_port_writeDataAddr_bits,
  output [127:0] io_port_writeDataBits,
  output [15:0]  io_port_writeDataStrb
);

  wire sourceValid_0 = io_source_0_readDataAddr_valid | io_source_0_writeDataAddr_valid;
  wire sourceValid_1 = io_source_1_readDataAddr_valid | io_source_1_writeDataAddr_valid;
  wire sourceValid_2 = io_source_2_readDataAddr_valid | io_source_2_writeDataAddr_valid;
  assign io_source_0_readData_bits = io_port_readData_bits;
  assign io_source_1_readData_valid = io_port_readData_valid;
  assign io_source_1_readData_bits = io_port_readData_bits;
  assign io_source_2_readData_valid = io_port_readData_valid;
  assign io_source_2_readData_bits = io_port_readData_bits;
  assign io_fabricBusy_1 = sourceValid_0;
  assign io_port_readDataAddr_valid =
    sourceValid_0
      ? io_source_0_readDataAddr_valid
      : sourceValid_1
          ? io_source_1_readDataAddr_valid
          : sourceValid_2 & io_source_2_readDataAddr_valid;
  assign io_port_readDataAddr_bits =
    sourceValid_0
      ? io_source_0_readDataAddr_bits
      : sourceValid_1
          ? io_source_1_readDataAddr_bits
          : sourceValid_2 ? io_source_2_readDataAddr_bits : 32'h0;
  assign io_port_writeDataAddr_valid =
    sourceValid_0
      ? io_source_0_writeDataAddr_valid
      : sourceValid_1
          ? io_source_1_writeDataAddr_valid
          : sourceValid_2 & io_source_2_writeDataAddr_valid;
  assign io_port_writeDataAddr_bits =
    sourceValid_0
      ? io_source_0_writeDataAddr_bits
      : sourceValid_1
          ? io_source_1_writeDataAddr_bits
          : sourceValid_2 ? io_source_2_writeDataAddr_bits : 32'h0;
  assign io_port_writeDataBits =
    sourceValid_0
      ? io_source_0_writeDataBits
      : sourceValid_1
          ? io_source_1_writeDataBits
          : sourceValid_2 ? io_source_2_writeDataBits : 128'h0;
  assign io_port_writeDataStrb =
    sourceValid_0
      ? io_source_0_writeDataStrb
      : sourceValid_1
          ? io_source_1_writeDataStrb
          : sourceValid_2 ? io_source_2_writeDataStrb : 16'h0;
endmodule

module IBus2Axi(
  input          clock,
                 reset,
                 io_ibus_valid,
  output         io_ibus_ready,
  input  [31:0]  io_ibus_addr,
  output [127:0] io_ibus_rdata,
  output         io_ibus_fault_valid,
  input          io_axi_addr_ready,
  output         io_axi_addr_valid,
  output [31:0]  io_axi_addr_bits_addr,
  input          io_axi_data_valid,
  input  [127:0] io_axi_data_bits_data,
  input  [1:0]   io_axi_data_bits_resp
);

  reg          sraddrActive;
  reg  [31:0]  saddrReg;
  reg  [127:0] sdata;
  reg  [1:0]   sresp;
  reg          sdataValid;
  wire [31:0]  saddr = {io_ibus_addr[31:4], 4'h0};
  wire         io_ibus_ready_0 =
    (io_axi_data_valid & sraddrActive | sdataValid) & saddr == saddrReg;
  wire         io_axi_addr_valid_0 =
    io_ibus_valid & ~sraddrActive & (~sdataValid | saddr != saddrReg);
  wire         _saddrReg_T = io_axi_addr_ready & io_axi_addr_valid_0;
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      sraddrActive <= 1'h0;
      saddrReg <= 32'h0;
      sdata <= 128'h0;
      sresp <= 2'h0;
      sdataValid <= 1'h0;
    end
    else begin
      sraddrActive <= ~io_axi_data_valid & (_saddrReg_T | sraddrActive);
      if (_saddrReg_T)
        saddrReg <= saddr;
      if (io_axi_data_valid) begin
        sdata <= io_axi_data_bits_data;
        sresp <= io_axi_data_bits_resp;
      end
      sdataValid <=
        io_axi_data_valid
          ? ~io_ibus_ready_0
          : ~(io_ibus_ready_0 & io_ibus_valid | _saddrReg_T) & sdataValid;
    end
  end // always @(posedge, posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    logic [31:0] _RANDOM[0:5];
    initial begin
      `ifdef INIT_RANDOM_PROLOG_
        `INIT_RANDOM_PROLOG_
      `endif // INIT_RANDOM_PROLOG_
      `ifdef RANDOMIZE_REG_INIT
        for (logic [2:0] i = 3'h0; i < 3'h6; i += 3'h1) begin
          _RANDOM[i] = `RANDOM;
        end
        sraddrActive = _RANDOM[3'h0][0];
        saddrReg = {_RANDOM[3'h0][31:1], _RANDOM[3'h1][0]};
        sdata =
          {_RANDOM[3'h1][31:1],
           _RANDOM[3'h2],
           _RANDOM[3'h3],
           _RANDOM[3'h4],
           _RANDOM[3'h5][0]};
        sresp = _RANDOM[3'h5][2:1];
        sdataValid = _RANDOM[3'h5][3];
      `endif // RANDOMIZE_REG_INIT
      if (reset) begin
        sraddrActive = 1'h0;
        saddrReg = 32'h0;
        sdata = 128'h0;
        sresp = 2'h0;
        sdataValid = 1'h0;
      end
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  assign io_ibus_ready = io_ibus_ready_0;
  assign io_ibus_rdata = sdata;
  assign io_ibus_fault_valid =
    io_ibus_ready_0 & (|(io_axi_data_valid ? io_axi_data_bits_resp : sresp));
  assign io_axi_addr_valid = io_axi_addr_valid_0;
  assign io_axi_addr_bits_addr = saddr;
endmodule

