        .SLP(1'b0),
        .DSLP(1'b0),
        .SD(1'b0),
        .CLK(clock),
        .CEB(~enable),
        .WEB(~write),
        .A(addr),
        .D(wdata),
        .BWEB(nwmask),
        .CEBM(1'b0),
        .WEBM(1'b0),
        .AM(9'b0),
